use craft_anything_formats::node_sea::NodeSea;
use craft_anything_formats::packed::PackedFormat;
use craft_anything_testkit::packed::{SeaBlob, sea_blob};

// Generated by the official Node.js v25.7.0 Linux x64 release using --experimental-sea-config.
// The scripts below, asset "retained asset\n", execArgv ["--no-warnings"] and extension "none"
// were supplied as inputs; the fixture bytes themselves come from Node's writer.
const CJS_SOURCE: &[u8] = b"const value = 2 + 3; console.log('sea-commonjs', value);\n";
const ESM_SOURCE: &[u8] = b"import { strictEqual } from 'node:assert'; strictEqual(2 + 3, 5); console.log('sea-module');\n";

fn native(mode: &str) -> Vec<u8> {
    let hex = match mode {
        "commonjs" => include_str!("fixtures/node_sea/v25_7_commonjs.hex"),
        "module" => include_str!("fixtures/node_sea/v25_7_module.hex"),
        _ => panic!("unknown fixture"),
    };
    let hex = hex.trim();
    assert_eq!(hex.len() % 2, 0);
    hex.as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| (char::from(pair[0]).to_digit(16).unwrap() * 16 + char::from(pair[1]).to_digit(16).unwrap()) as u8)
        .collect()
}

fn check_native(mode: &str, script: &str, source: &[u8]) {
    let bytes = native(mode);
    assert!(NodeSea.detect(&bytes));
    let listing = NodeSea.list(&bytes).unwrap();
    assert_eq!(listing.facts["layout"], "with_module_format");
    assert_eq!(listing.facts["module_format"], mode);
    assert_eq!(listing.facts["code_path"], script);
    assert_eq!(listing.facts["exec_argv_extension"], 0);
    assert_eq!(listing.facts["exec_argv"][0], "--no-warnings");
    assert_eq!(listing.facts["assets"], 1);
    assert!(!listing.truncated);
    assert_eq!(listing.entries.len(), 2);
    assert_eq!(listing.entries[0].path, format!("main/{script}"));
    assert_eq!(NodeSea.read(&bytes, &listing.entries[0], source.len() as u64).unwrap(), source);
    assert_eq!(listing.entries[1].path, "assets/docs/note.txt");
    assert_eq!(NodeSea.read(&bytes, &listing.entries[1], b"retained asset\n".len() as u64).unwrap(), b"retained asset\n");
}

#[test]
fn current_commonjs_blob_reads_the_script_and_assets_at_their_native_offsets() {
    check_native("commonjs", "main.cjs", CJS_SOURCE);
}

#[test]
fn current_module_blob_reads_the_script_and_assets_at_their_native_offsets() {
    check_native("module", "main.mjs", ESM_SOURCE);
}

#[test]
fn older_layouts_keep_their_original_offsets_and_unspecified_module_format() {
    for layout in 1..=3 {
        let bytes = sea_blob(&SeaBlob { code_path: "legacy.js", code: b"legacy script", assets: &[("note", b"old asset")], ..Default::default() }, layout);
        let listing = NodeSea.list(&bytes).unwrap();
        assert!(listing.facts["module_format"].is_null());
        assert_eq!(NodeSea.read(&bytes, &listing.entries[0], 100).unwrap(), b"legacy script");
        assert_eq!(NodeSea.read(&bytes, &listing.entries[1], 100).unwrap(), b"old asset");
        assert_eq!(
            listing.facts["layout"],
            match layout {
                1 => "code_only",
                2 => "with_code_path",
                _ => "with_exec_argv_extension",
            }
        );
    }
}

#[test]
fn unknown_module_tags_and_incomplete_new_layouts_are_refused() {
    for mode in ["commonjs", "module"] {
        let mut bytes = native(mode);
        bytes[9] = 2;
        assert!(NodeSea.list(&bytes).is_err());
        let mut bytes = native(mode);
        bytes.pop();
        assert!(NodeSea.list(&bytes).is_err());
        let mut bytes = native(mode);
        bytes.push(1);
        assert!(NodeSea.list(&bytes).is_err());
    }
}

#[test]
fn current_layout_keeps_metadata_limits_and_validates_omitted_fields() {
    let key = "k".repeat(8 * 1024 * 1024);
    let mut bytes = sea_blob(
        &SeaBlob {
            code_path: "main.mjs",
            code: b"source",
            assets: &[(&key, b"large"), ("kept", b"small")],
            exec_argv: &["--no-warnings"],
            ..Default::default()
        },
        3,
    );
    bytes.insert(9, 1);
    let listing = NodeSea.list(&bytes).unwrap();
    assert!(listing.truncated);
    assert_eq!(listing.facts["module_format"], "module");
    assert_eq!(listing.facts["assets"], 2);
    assert_eq!(listing.facts["assets_listed"], 1);
    assert_eq!(listing.entries[1].path, "assets/kept");
    assert_eq!(NodeSea.read(&bytes, &listing.entries[1], 5).unwrap(), b"small");
    assert_eq!(listing.facts["exec_argv"][0], "--no-warnings");
    bytes.pop();
    assert!(NodeSea.list(&bytes).is_err());
}
